323	/**
324	 * @brief 返回 s 的 UTF-8 前缀长度：不超过 max_bytes，且不切断多字节字符。
325	 */
326	static size_t bicycle_ui_ctl_utf8_prefix(const char * s, size_t max_bytes)
327	{
328	    size_t n = 0u;
329	
330	    while (s != NULL && s[n] != '\0' && n < max_bytes) {
331	        const unsigned char c = (unsigned char)s[n];
332	        size_t len = 1u;
333	
334	        if ((c & 0xE0u) == 0xC0u) {
335	            len = 2u;
336	        } else if ((c & 0xF0u) == 0xE0u) {
337	            len = 3u;
338	        } else if ((c & 0xF8u) == 0xF0u) {
339	            len = 4u;
340	        }
341	        if (n + len > max_bytes) {
342	            break;
343	        }
344	        n += len;
345	    }
346	
347	    return n;
348	}
